#include <list>
#include <iostream>

int main() {
    std::list<int> L = {10, 20, 30};

    // Iterator 'it' points to 20
    auto it = ++L.begin(); 

    // Insert new elements (does not invalidate 'it')
    L.push_front(5);
    L.insert(L.end(), 40);

    // 'it' still points to 20
    std::cout << "Iterator value: " << *it << std::endl; // Output: 20

    // Erase 10 (does not invalidate 'it')
    L.erase(L.begin()); 

    std::cout << "Iterator value after erase: " << *it << std::endl; // Output: 20
}
